/*
Given an array of `n` distinct 2D integer points and `m` query points (all coordinates are integers, and coordinates can be negative, zero, or positive), write a C++ function `vector<int> countRightAnglePairs(const vector<Point>& pts, const vector<Point>& queries)` that, for each query point `q`, returns the number of unordered pairs of distinct points `(A, B)` from `pts` such that the segments `q-A` and `q-B` are perpendicular (i.e., the angle at `q` is exactly 90 degrees). The function must treat points as exact long long coordinates, and a pair `(A,B)` is counted once regardless of order. The input points are all distinct, but a query point may coincide with one or more points in `pts`; in that case, a degenerate segment of length zero is not considered perpendicular to anything, so pairs involving the query point itself are excluded. The solution must be efficient enough for up to `n = 2e5` and `m = 2e5` total, using hashing with canonical direction keys. The return vector has size `m`, with the i-th element being the answer for `queries[i]`.
*/
#include <vector>
#include <unordered_map>
#include <cstdint>

struct Point {
    long long x, y;
    bool operator==(const Point& other) const {
        return x == other.x && y == other.y;
    }
};

struct PointHash {
    std::size_t operator()(const Point& p) const {
        return std::hash<long long>()(p.x) ^ (std::hash<long long>()(p.y) << 1);
    }
};

// Rotate a vector 90 degrees counterclockwise.
Point rotate90(const Point& p) {
    return Point{-p.y, p.x};
}

// Rotate a vector 90 degrees clockwise (or -90 counterclockwise).
Point rotateNeg90(const Point& p) {
    return Point{p.y, -p.x};
}

// For each query point, count unordered pairs of distinct input points
// such that the segments from the query to the two points are perpendicular.
std::vector<int> countRightAnglePairs(const std::vector<Point>& pts,
                                      const std::vector<Point>& queries) {
    int n = static_cast<int>(pts.size());
    int m = static_cast<int>(queries.size());
    std::vector<int> ans(m, 0);

    for (int qi = 0; qi < m; ++qi) {
        const Point& q = queries[qi];

        // Count all nonzero vectors from q to each point.
        std::unordered_map<Point, int, PointHash> cnt;
        for (const Point& p : pts) {
            Point vec{p.x - q.x, p.y - q.y};
            if (vec.x != 0 || vec.y != 0) {
                ++cnt[vec];
            }
        }

        int64_t total = 0;
        for (const Point& p : pts) {
            Point u{p.x - q.x, p.y - q.y};
            if (u.x == 0 && u.y == 0) continue;  // Skip the coincident point.

            Point r1 = rotate90(u);
            Point r2 = rotateNeg90(u);

            total += cnt[r1] + cnt[r2];
        }

        // Each unordered pair is counted twice (once from each endpoint).
        ans[qi] = static_cast<int>(total / 2);
    }

    return ans;
}
